INSERT INTO `answers` (`id`, `question_version_id`, `answer_text`, `answer_order`, `is_correct`, `is_active`, `deleted_at`, `created_at`, `updated_at`) VALUES (6624,1656,'Nic więcej nie jest potrzebne - samo odłączenie od sieci w pełni zabezpiecza',4,0,1,NULL,'2026-08-02 20:34:47','2026-08-02 20:34:47');
INSERT INTO `answers` (`id`, `question_version_id`, `answer_text`, `answer_order`, `is_correct`, `is_active`, `deleted_at`, `created_at`, `updated_at`) VALUES (6625,1657,'Rozładować własny ładunek elektrostatyczny (np. opaską antystatyczną)',1,1,1,NULL,'2026-08-02 20:34:47','2026-08-02 20:34:47');
